 const stick=document.getElementById('stick'),knob=document.getElementById('knob');let stickId=null;function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=r.width*.34;if(len>max){dx*=max/len;dy*=max/len}joystick.x=dx/max;joystick.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function resetStick(e){if(e.pointerId===stickId){stickId=null;joystick={x:0,y:0};knob.style.transform=''}}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
 async function enableTilt(){if(!('DeviceOrientationEvent'in window)){showToast('Tilt controls are not available on this device');return}try{if(typeof DeviceOrientationEvent.requestPermission==='function'){let p=await DeviceOrientationEvent.requestPermission();if(p!=='granted'){showToast('Motion permission was not granted');return}}tiltEnabled=true;addEventListener('deviceorientation',e=>{tilt.x=Math.max(-.7,Math.min(.7,(e.gamma||0)/35));tilt.y=Math.max(-.7,Math.min(.7,(e.beta||0)/35))});document.getElementById('tilt').style.color='#b6ed9c';showToast('Tilt controls enabled')}catch(err){showToast('Could not enable motion controls')}}document.getElementById('tilt').addEventListener('click',enableTilt);document.getElementById('introTilt').addEventListener('click',enableTilt);
